import{_ as e,c as t,o as a,a2 as s}from"./chunks/framework._4mWlOLd.js";const o=JSON.parse('{"title":"Technical Architecture - BrandPulse","description":"How BrandPulse processes 700k social media posts per second.","frontmatter":{"title":"Technical Architecture - BrandPulse","description":"How BrandPulse processes 700k social media posts per second."},"headers":[],"relativePath":"docs/brandpulse/technical-arch.md","filePath":"docs/brandpulse/technical-arch.md","lastUpdated":1741636004000}');const n=e({name:"docs/brandpulse/technical-arch.md"},[["render",function(e,o,n,i,r,l){return a(),t("div",null,o[0]||(o[0]=[s('<h1 id="technical-architecture" tabindex="-1">Technical Architecture <a class="header-anchor" href="#technical-architecture" aria-label="Permalink to &quot;Technical Architecture&quot;">​</a></h1><p>Time to peek under the hood of <strong>BrandPulse</strong>—this thing cranks through 700,000 tweets a second and turns them into real-time sentiment insights without breaking a sweat. I pieced it together with Node.js, Kafka, and InfluxDB, and here’s how it all flows to handle that kind of madness.</p><h2 id="the-big-picture" tabindex="-1">The Big Picture <a class="header-anchor" href="#the-big-picture" aria-label="Permalink to &quot;The Big Picture&quot;">​</a></h2><p>BrandPulse is like a well-oiled machine: it generates a ton of fake tweets, streams them fast, ingests the data, and throws it up on a dashboard—all live. It’s built to scale up, stay snappy, and not choke when the volume’s insane. Check out the flow:</p><h3 id="architecture-diagram" tabindex="-1">Architecture Diagram <a class="header-anchor" href="#architecture-diagram" aria-label="Permalink to &quot;Architecture Diagram&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+----------------+      +----------------+      +----------------+      +----------------+</span></span>\n<span class="line"><span>| Node.js Workers| --&gt;  | Kafka          | --&gt;  | Node.js Consumer| --&gt;  | InfluxDB       |</span></span>\n<span class="line"><span>| (Data Gen)     |      | (tweets topic) |      | (Data Ingestion)|      | (Storage)      |</span></span>\n<span class="line"><span>+----------------+      +----------------+      +----------------+      +----------------+</span></span>\n<span class="line"><span>       ^                         |                           |</span></span>\n<span class="line"><span>       |                         |                           |</span></span>\n<span class="line"><span>       |                  +----------------+                 |</span></span>\n<span class="line"><span>       +----------------- | Web App         | &lt;---------------+</span></span>\n<span class="line"><span>                          | (Express + Socket.io) |</span></span>\n<span class="line"><span>                          +----------------+</span></span></code></pre></div><h2 id="the-components" tabindex="-1">The Components <a class="header-anchor" href="#the-components" aria-label="Permalink to &quot;The Components&quot;">​</a></h2><p>I split it into four main chunks—each one’s got a job to keep the whole thing humming.</p><h3 id="_1-data-generation-node-js-workers" tabindex="-1">1. Data Generation (Node.js Workers) <a class="header-anchor" href="#_1-data-generation-node-js-workers" aria-label="Permalink to &quot;1. Data Generation (Node.js Workers)&quot;">​</a></h3><ul><li><strong>What It Does</strong>: This is where I whip up 700k tweets a second about &quot;SuperCoffee&quot;—stuff like “SuperCoffee’s the best!” or “This coffee’s gross.”</li><li><strong>How It Works</strong>: Node.js with worker threads fires up multiple workers, each spitting out tweets with <code>tweetId</code>, <code>timestamp</code>, <code>text</code>, <code>brand</code>, and <code>sentiment</code>. Sentiment’s a quick rule-based call—“awesome” tags positive, “awful” tags negative, rest is neutral.</li><li><strong>Why Node.js?</strong>: It’s killer for I/O-heavy tasks like this, and workers let me squeeze every core for max output.</li><li><strong>Output</strong>: Tweets get wrapped in Avro and shot over to Kafka.</li></ul><h3 id="_2-data-streaming-kafka" tabindex="-1">2. Data Streaming (Kafka) <a class="header-anchor" href="#_2-data-streaming-kafka" aria-label="Permalink to &quot;2. Data Streaming (Kafka)&quot;">​</a></h3><ul><li><strong>What It Does</strong>: Kafka’s the backbone—hauling all those tweets without dropping a beat.</li><li><strong>How It Works</strong>: I’ve got a <code>tweets</code> topic where workers dump Avro messages. Kafka’s tuned for high throughput with multiple partitions to manage the 700k flood.</li><li><strong>Why Kafka?</strong>: It’s bulletproof for streaming big data, and I can scale it out if I need more horsepower later.</li></ul><h3 id="_3-data-ingestion-node-js-consumer-influxdb" tabindex="-1">3. Data Ingestion (Node.js Consumer + InfluxDB) <a class="header-anchor" href="#_3-data-ingestion-node-js-consumer-influxdb" aria-label="Permalink to &quot;3. Data Ingestion (Node.js Consumer + InfluxDB)&quot;">​</a></h3><ul><li><strong>What It Does</strong>: This grabs tweets from Kafka and ingests them into InfluxDB for fast crunching.</li><li><strong>How It Works</strong>: A Node.js consumer listens on the <code>tweets</code> topic, pulls messages, and unpacks the Avro into JSON. I batch them—maybe 1000 tweets or every second—and shove them into InfluxDB. It’s stored as a <code>tweets</code> measurement with tags like <code>brand</code> and <code>sentiment</code>, plus <code>text</code> as a field.</li><li><strong>Why InfluxDB?</strong>: It’s a time-series beast, perfect for tracking changes over seconds—like sentiment swings. Batching keeps it from choking at 700k req/sec.</li></ul><h3 id="_4-web-application-express-socket-io" tabindex="-1">4. Web Application (Express + Socket.io) <a class="header-anchor" href="#_4-web-application-express-socket-io" aria-label="Permalink to &quot;4. Web Application (Express + Socket.io)&quot;">​</a></h3><ul><li><strong>What It Does</strong>: This is the flashy part—showing live sentiment on a dashboard.</li><li><strong>How It Works</strong>: An Express server pings InfluxDB every second (e.g., “Count positive tweets from the last 10 seconds”), then pushes updates to the browser via Socket.io. The dashboard rocks a pie chart (Chart.js), a counter locked at 700k, and an alert if negatives spike over 50%. Buttons let me start/stop the tweet storm or tweak sentiment on the fly.</li><li><strong>Why This Stack?</strong>: Express keeps it lean, Socket.io handles real-time like a pro, and Chart.js makes it pop visually.</li></ul><h2 id="how-it-flows" tabindex="-1">How It Flows <a class="header-anchor" href="#how-it-flows" aria-label="Permalink to &quot;How It Flows&quot;">​</a></h2><p>Workers blast tweets into Kafka, the consumer ingests them into InfluxDB, and the web app pulls counts to show live. Hit “start” on the dashboard? A control message zips through Kafka to kick the workers off—keeps it clean since I’m already streaming everything there. It’s fast, smooth, and takes the 700k load in stride.</p><h2 id="technical-highlights" tabindex="-1">Technical Highlights <a class="header-anchor" href="#technical-highlights" aria-label="Permalink to &quot;Technical Highlights&quot;">​</a></h2><ul><li><strong>Speed</strong>: Sub-second from tweet to screen—blink and it’s there.</li><li><strong>Scale</strong>: 700k req/sec is nuts (Twitter peaks around that for huge events), but it proves I can handle the big leagues.</li><li><strong>Choices</strong>: Node.js for speed, Kafka for streaming, InfluxDB for time-series—picked to keep it flying at this rate.</li></ul>',20)]))}]]);export{o as __pageData,n as default};
